CREATE DATABASE IF NOT EXISTS cinebook CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE cinebook;
CREATE TABLE IF NOT EXISTS customers (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('customer','admin') NOT NULL DEFAULT 'customer',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS movies (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(180) NOT NULL,genre VARCHAR(80) NOT NULL,language VARCHAR(60) NOT NULL,duration_minutes SMALLINT UNSIGNED NOT NULL,rating DECIMAL(3,1),release_year YEAR NOT NULL,certificate VARCHAR(20),poster_url TEXT,backdrop_url TEXT,synopsis TEXT,cast_json JSON,director VARCHAR(150),base_price DECIMAL(10,2) NOT NULL DEFAULT 200.00,status ENUM('Now Showing','Coming Soon') NOT NULL DEFAULT 'Now Showing',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS theatres (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(180) NOT NULL,address VARCHAR(255) NOT NULL,city VARCHAR(100) NOT NULL,amenities JSON,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX idx_theatres_city(city));
CREATE TABLE IF NOT EXISTS screens (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,theatre_id BIGINT UNSIGNED NOT NULL,name VARCHAR(80) NOT NULL,format VARCHAR(80),total_seats SMALLINT UNSIGNED NOT NULL DEFAULT 0,FOREIGN KEY(theatre_id) REFERENCES theatres(id) ON DELETE CASCADE,UNIQUE KEY uq_screen_name_per_theatre(theatre_id,name));
CREATE TABLE IF NOT EXISTS seats (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,screen_id BIGINT UNSIGNED NOT NULL,seat_row CHAR(2) NOT NULL,seat_number SMALLINT UNSIGNED NOT NULL,seat_type ENUM('standard','premium','recliner') NOT NULL DEFAULT 'standard',FOREIGN KEY(screen_id) REFERENCES screens(id) ON DELETE CASCADE,UNIQUE KEY uq_seat_position(screen_id,seat_row,seat_number));
CREATE TABLE IF NOT EXISTS shows (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,movie_id BIGINT UNSIGNED NOT NULL,screen_id BIGINT UNSIGNED NOT NULL,starts_at DATETIME NOT NULL,ends_at DATETIME NOT NULL,price DECIMAL(10,2) NOT NULL,language VARCHAR(60) NOT NULL,format VARCHAR(80),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(movie_id) REFERENCES movies(id),FOREIGN KEY(screen_id) REFERENCES screens(id),INDEX idx_shows_movie_date(movie_id,starts_at),INDEX idx_shows_screen_date(screen_id,starts_at));
CREATE TABLE IF NOT EXISTS bookings (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,booking_code CHAR(36) NOT NULL UNIQUE,customer_id BIGINT UNSIGNED NOT NULL,show_id BIGINT UNSIGNED NOT NULL,status ENUM('PENDING','CONFIRMED','CANCELLED') NOT NULL DEFAULT 'PENDING',total_amount DECIMAL(10,2) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(customer_id) REFERENCES customers(id),FOREIGN KEY(show_id) REFERENCES shows(id),INDEX idx_bookings_customer(customer_id,created_at));
CREATE TABLE IF NOT EXISTS booking_seats (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,booking_id BIGINT UNSIGNED NOT NULL,show_id BIGINT UNSIGNED NOT NULL,seat_id BIGINT UNSIGNED NOT NULL,unit_price DECIMAL(10,2) NOT NULL,FOREIGN KEY(booking_id) REFERENCES bookings(id) ON DELETE CASCADE,FOREIGN KEY(show_id) REFERENCES shows(id),FOREIGN KEY(seat_id) REFERENCES seats(id),UNIQUE KEY uq_show_seat(show_id,seat_id),INDEX idx_booking_seats_booking(booking_id));
CREATE TABLE IF NOT EXISTS tickets (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,booking_id BIGINT UNSIGNED NOT NULL,ticket_code VARCHAR(80) NOT NULL UNIQUE,issued_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(booking_id) REFERENCES bookings(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS payments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,booking_id BIGINT UNSIGNED NOT NULL,amount DECIMAL(10,2) NOT NULL,method ENUM('DEMO','CARD','UPI','NETBANKING') NOT NULL DEFAULT 'DEMO',status ENUM('PENDING','SUCCESS','FAILED','REFUNDED') NOT NULL DEFAULT 'PENDING',transaction_reference VARCHAR(120),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(booking_id) REFERENCES bookings(id) ON DELETE CASCADE);
